<?php
require_role('admin');
$system=geo_system();$queues=admin_assignment_counts();$overdue=staff_overdue_sql();
$stats=q("SELECT COALESCE(SUM(status NOT IN ('Resolved','Rejected','Duplicate')),0) open_count,COALESCE(SUM(".$overdue."),0) overdue,COALESCE(SUM(priority='High' AND status NOT IN ('Resolved','Rejected','Duplicate')),0) high_count,COALESCE(SUM(status='Awaiting Approval'),0) approval FROM issues i")->fetch();
$attention=q(issue_query()." WHERE i.duplicate_of IS NULL AND i.status NOT IN ('Resolved','Rejected','Duplicate') AND (i.status IN ('Submitted','Verified','Awaiting Approval') OR ".$overdue." OR i.priority='High') ORDER BY CASE WHEN i.status='Awaiting Approval' THEN 0 WHEN ".$overdue." THEN 1 WHEN i.priority='High' THEN 2 WHEN i.status='Submitted' THEN 3 ELSE 4 END,i.created_at,i.id LIMIT 8")->fetchAll();
$legacy=0;$missing_provinces=0;$missing_districts=0;
if($system){
 $legacy=(int)geo_raw('SELECT COUNT(*) FROM issues WHERE province_id IS NULL OR district_id IS NULL OR town_id IS NULL')->fetchColumn();
 $missing_provinces=(int)geo_raw("SELECT COUNT(*) FROM geo_provinces p LEFT JOIN users u ON u.id=p.admin_id WHERE u.id IS NULL OR u.active=0 OR u.role<>'admin' OR u.is_system_admin=1")->fetchColumn();
 $missing_districts=(int)geo_raw("SELECT COUNT(*) FROM geo_districts d LEFT JOIN users u ON u.id=d.officer_id WHERE u.id IS NULL OR u.active=0 OR u.role<>'officer'")->fetchColumn();
}
admin_page_start($system?'System overview':'Province operations',$system?'Monitor reports across all provinces, routing readiness and system health.':'Review reports in your province, assign District Officers and approve completed work.');
if($system){$period=oversight_period();$activityWhere=$period['from']?'created_at>=? AND created_at<?':'1=1';$activityParams=$period['from']?[$period['from'].' 00:00:00',$period['to'].' 00:00:00']:[];$received=(int)geo_raw('SELECT COUNT(*) FROM issues WHERE '.$activityWhere,$activityParams)->fetchColumn();$exceptionCount=(int)geo_raw('SELECT COUNT(*) FROM issues i WHERE '.oversight_exception_sql())->fetchColumn();
?><section class="panel oversight-toolbar"><div class="row between"><div><strong>National oversight</strong><p class="small muted">Current workload stays current; activity below uses the selected period.</p></div><a class="button secondary" href="index.php?page=oversight">Compare all provinces →</a></div><form method="get" class="row"><input type="hidden" name="page" value="dashboard"><label>Activity period<select name="period"><?php foreach(['today'=>'Today','week'=>'Last 7 days','month'=>'This month','all'=>'All dates'] as $k=>$label):?><option value="<?=$k?>" <?=$period['key']===$k?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="button secondary">Apply</button><span><?=$received?> reports received · <?=e($period['label'])?></span></form><div class="row"><a class="text-link" href="index.php?page=oversight&amp;tab=exceptions">Routing exceptions (<?=$exceptionCount?>) →</a><a class="text-link" href="index.php?page=oversight&amp;tab=coverage&amp;missing=1">Towns without active teams →</a><a class="text-link" href="index.php?page=oversight&amp;tab=reminders">Overdue follow-up →</a></div></section><?php }
echo '<p class="small"><a class="text-link" href="index.php?page=flow">Workflow queues · location checks, blocked work and reopen requests →</a></p>';
if($system)echo '<p><a class="text-link" href="index.php?page=readiness">Setup checks · category targets · temporary cover · scheduled follow-up →</a></p>';
$cards=[['Open reports',$stats['open_count'],'Current open work','reports','▤'],['Needs review',$queues['review'],'Review submitted reports','assignments&view=review','▤'],['Ready to assign',$queues['ready'],'Choose a District Officer','assignments&view=ready','⇢'],['Province final approval',$stats['approval'],'Review completion evidence','reports&view=approval','✓'],['Overdue',$stats['overdue'],'Review delayed work','reports&view=overdue','◷'],['High priority',$stats['high_count'],'Check urgent reports','reports&view=high','!']];
?><section class="admin-summary-grid dashboard-summary" aria-label="Current report counts"><?php foreach($cards as $c):?><a class="stat" href="<?=e('index.php?page='.$c[3])?>"><div class="row between"><span><?=e($c[0])?></span><b class="stat-icon" aria-hidden="true"><?=e($c[4])?></b></div><strong><?=(int)$c[1]?></strong><small><?=e($c[2])?> →</small></a><?php endforeach;?></section>
<p class="small muted dashboard-scope"><?=$system?'Counts cover all provinces.':'Counts cover only your assigned province.'?> Open reports include work in progress and awaiting approval; the cards may overlap.</p>
<?php if((int)$queues['confirmation']>0):?><div class="admin-notice dashboard-notice"><strong><?=(int)$queues['confirmation']?> assignment(s) to verify.</strong> Older verified reports already have an officer recorded. <a href="index.php?page=assignments&amp;view=confirmation">Verify assignments →</a></div><?php endif;?>
<section class="panel dashboard-attention"><div class="row between"><h2>Needs attention</h2><?php if($attention):?><a class="text-link" href="index.php?page=reports">View all reports →</a><?php endif;?></div>
<?php if(!$attention):?><p class="small muted dashboard-empty">No reports currently need review, assignment, approval or urgent follow-up.</p><?php else:?><p class="small muted">Up to 8 reports. Approvals first, then overdue and high priority work.</p><div class="table-wrap"><table><thead><tr><th>Report</th><th>Province / District</th><th>Status</th><th>Priority</th><th>Next action</th></tr></thead><tbody><?php foreach($attention as $i):
 $classified=$i['province_id']&&$i['district_id']&&$i['town_id'];$url='index.php?page=issue&id='.(int)$i['id'];$action='Review report';
 if(!$classified&&$system){$url='index.php?page=routing&tab=legacy';$action='Classify location';}
 elseif($i['status']==='Awaiting Approval'){$action='Review completion';}
 elseif($i['status']==='Verified'){$confirm=!empty($i['officer_id']);$url='index.php?page=assignments&view='.($confirm?'confirmation':'ready').'&id='.(int)$i['id'].'#assignment';$action=$confirm?'Verify assignment':'Assign officer';}
 elseif($i['status']!=='Submitted'){$action='Follow up';}
?><tr><td><a class="table-title" href="index.php?page=issue&amp;id=<?=(int)$i['id']?>">#<?=(int)$i['id']?> · <?=e($i['title'])?></a><small class="muted"><?=e($i['town_name']?:'Town not classified')?></small></td><td><?=e($i['province_name']?:'Not classified')?><br><small class="muted"><?=e($i['district_name']?:'District not classified')?></small></td><td><?=badge($i['status'])?></td><td><span class="priority-chip p-<?=e(strtolower($i['priority']))?>"><?=e($i['priority'])?></span></td><td><a class="button secondary" href="<?=e($url)?>"><?=e($action)?> →</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if(!(int)$stats['approval']):?><p class="small muted dashboard-clear"><span aria-hidden="true">✓</span> No completion requests are waiting for final approval.</p><?php endif;?>
<?php if($system&&($legacy||$missing_provinces||$missing_districts||!class_exists('ZipArchive'))):?><section class="panel dashboard-setup section-space"><h2>Setup & system health</h2>
<?php if($legacy):?><div class="dashboard-health-row"><p><strong><?=$legacy?> legacy report(s) need location classification.</strong><br><span class="muted">Set Province, District and Town to route these reports.</span></p><a class="text-link" href="index.php?page=routing&amp;tab=legacy">Classify reports →</a></div><?php endif;?>
<?php if($missing_provinces||$missing_districts):?><div class="dashboard-health-row"><p><strong>Routing responsibility needs attention.</strong><br><span class="muted"><?=$missing_provinces?> province(s) and <?=$missing_districts?> district(s) need an active responsible account.</span></p><a class="text-link" href="index.php?page=routing">Review routing →</a></div><?php endif;?>
<?php if(!class_exists('ZipArchive')):?><div class="dashboard-health-row"><p><strong>ZIP backups are unavailable.</strong></p><a class="text-link" href="index.php?page=system">View system health →</a></div><?php endif;?></section><?php endif;?>
<?php admin_page_end();
